const std = @import("std"); const builtin = @import("builtin"); const spawn = @import("spawn"); const netz = std.Io.net;
const evprobbase = @import("ev-prob-base.zig"); const ArmzErro = evprobbase.ArmzErro; const CF = evprobbase.CF; const Cond = evprobbase.Cond; const Kind = evprobbase.Kind; const duraPars = evprobbase.duraPars; const sizePars = evprobbase.sizePars;
const wapi = struct {
const BOOL = i32; const DWORD = u32; const ULONGLONG = u64; const BYTE = u8;
const LASTINPUTINFO = extern struct { cbSize: DWORD, dwTime: DWORD };
const SYSTEM_POWER_STATUS = extern struct { ACLineStatus: BYTE, BatteryFlag: BYTE, BatteryLifePercent: BYTE, SystemStatusFlag: BYTE, BatteryLifeTime: DWORD, BatteryFullLifeTime: DWORD };
extern "user32" fn GetLastInputInfo(plii: *LASTINPUTINFO) callconv(.winapi) BOOL;
extern "kernel32" fn GetTickCount64() callconv(.winapi) ULONGLONG;
extern "kernel32" fn GetSystemPowerStatus(sps: *SYSTEM_POWER_STATUS) callconv(.winapi) BOOL;
extern "kernel32" fn GetDiskFreeSpaceExW(dir: [*:0]const u16, free_to_caller: ?*ULONGLONG, total: ?*ULONGLONG, total_free: ?*ULONGLONG) callconv(.winapi) BOOL;
};
fn winzIdleMsec() ?u64 { if (comptime builtin.os.tag != .windows) return null; var liiz: wapi.LASTINPUTINFO = .{ .cbSize = @sizeOf(wapi.LASTINPUTINFO), .dwTime = 0 }; if (wapi.GetLastInputInfo(&liiz) == 0) return null; const tick: u32 = @truncate(wapi.GetTickCount64()); return @as(u64, tick -% liiz.dwTime); }
fn winzBattOnzz() ?bool { if (comptime builtin.os.tag != .windows) return null; var spsz: wapi.SYSTEM_POWER_STATUS = undefined; if (wapi.GetSystemPowerStatus(&spsz) == 0) return null; return switch (spsz.ACLineStatus) { 0 => true, 1 => false, else => null }; }
fn winzFreeByte(iozz: std.Io, path: []const u8) ?u64 { _ = iozz; if (comptime builtin.os.tag != .windows) return null; var wbuf: [std.fs.max_path_bytes]u16 = undefined; const leng = std.unicode.utf8ToUtf16Le(&wbuf, path) catch return null; if (leng + 1 > wbuf.len) return null; wbuf[leng] = 0; var free: u64 = 0; if (wapi.GetDiskFreeSpaceExW(@ptrCast(&wbuf), &free, null, null) == 0) return null; return free; }
pub fn procRunn(iozz: std.Io, name: []const u8) ?bool { if (name.len == 0) return null; return switch (builtin.os.tag) { .windows => winzProcRunn(name), .linux => linuProcRunn(iozz, name), .macos => maczProcRunn(iozz, name), else => null }; }
const wprc = struct {
const HANDLE = *anyopaque; const DWORD = u32; const BOOL = i32; const MAX_PATH = 260; const TH32CS_SNAPPROCESS: DWORD = 0x00000002;
const PROCESSENTRY32W = extern struct { dwSize: DWORD, cntUsage: DWORD, th32ProcessID: DWORD, th32DefaultHeapID: usize, th32ModuleID: DWORD, cntThreads: DWORD, th32ParentProcessID: DWORD, pcPriClassBase: i32, dwFlags: DWORD, szExeFile: [MAX_PATH]u16 };
extern "kernel32" fn CreateToolhelp32Snapshot(flags: DWORD, pid: DWORD) callconv(.winapi) ?HANDLE;
extern "kernel32" fn Process32FirstW(snap: HANDLE, pe: *PROCESSENTRY32W) callconv(.winapi) BOOL;
extern "kernel32" fn Process32NextW(snap: HANDLE, pe: *PROCESSENTRY32W) callconv(.winapi) BOOL;
extern "kernel32" fn CloseHandle(h: HANDLE) callconv(.winapi) BOOL;
};
fn winzProcRunn(name: []const u8) ?bool { if (comptime builtin.os.tag != .windows) return null; const snap = wprc.CreateToolhelp32Snapshot(wprc.TH32CS_SNAPPROCESS, 0) orelse return null; defer _ = wprc.CloseHandle(snap); var pezz: wprc.PROCESSENTRY32W = undefined; pezz.dwSize = @sizeOf(wprc.PROCESSENTRY32W); if (wprc.Process32FirstW(snap, &pezz) == 0) return null; var ubuf: [wprc.MAX_PATH * 3]u8 = undefined; while (true) { const wide = std.mem.sliceTo(&pezz.szExeFile, 0); if (std.unicode.utf16LeToUtf8(&ubuf, wide)) |leng| { if (std.ascii.eqlIgnoreCase(ubuf[0..leng], name)) return true; } else |_| {} if (wprc.Process32NextW(snap, &pezz) == 0) break; } return false; }
fn linuProcRunn(iozz: std.Io, name: []const u8) ?bool { var dirz = std.Io.Dir.cwd().openDir(iozz, "/proc", .{ .iterate = true }) catch return null; defer dirz.close(iozz); var iter = dirz.iterate(); var bufz: [64]u8 = undefined; while (iter.next(iozz) catch null) |entr| { if (entr.name.len == 0 or !std.ascii.isDigit(entr.name[0])) continue; var pbuf: [64]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, "{s}/comm", .{entr.name}) catch continue; const file = dirz.openFile(iozz, path, .{}) catch continue; defer file.close(iozz); var rdrz = file.reader(iozz, &bufz); const leng = rdrz.interface.readSliceShort(&bufz) catch continue; const comm = std.mem.trimEnd(u8, bufz[0..leng], "\n"); const want = if (name.len > 15) name[0..15] else name; if (std.mem.eql(u8, comm, want)) return true; } return false; }
// macOS statvfs by hand (no @cImport in 0.17): 32-bit block counts, padded tail
const cvfs = struct { const struct_statvfs = extern struct { f_bsize: c_ulong, f_frsize: c_ulong, f_blocks: u32, f_bfree: u32, f_bavail: u32, _rest: [64]u8 }; extern "c" fn statvfs(path: [*:0]const u8, buf: *struct_statvfs) c_int; };
const lvfs = struct { const StatVfs = extern struct { f_bsize: c_ulong, f_frsize: c_ulong, f_blocks: u64, f_bfree: u64, f_bavail: u64, _rest: [128]u8 }; extern "c" fn statvfs(path: [*:0]const u8, buf: *StatVfs) c_int; };
pub fn freeByte(iozz: std.Io, path: []const u8) ?u64 { if (comptime builtin.os.tag == .windows) return winzFreeByte(iozz, path); var zbuf: [std.fs.max_path_bytes]u8 = undefined; if (path.len + 1 > zbuf.len) return null; @memcpy(zbuf[0..path.len], path); zbuf[path.len] = 0; if (comptime builtin.os.tag == .linux) { var stat: lvfs.StatVfs = undefined; if (lvfs.statvfs(@ptrCast(&zbuf), &stat) != 0) return null; return stat.f_bavail * @as(u64, stat.f_frsize); } if (comptime builtin.os.tag == .macos) { var stat: cvfs.struct_statvfs = undefined; if (cvfs.statvfs(@ptrCast(&zbuf), &stat) != 0) return null; return @as(u64, @intCast(stat.f_bavail)) * @as(u64, @intCast(stat.f_frsize)); } return null; }
pub fn idleMsec(iozz: std.Io) ?u64 { var bufz: [4096]u8 = undefined; var fbaz = std.heap.FixedBufferAllocator.init(&bufz); const allo = fbaz.allocator(); switch (builtin.os.tag) { .windows => return winzIdleMsec(), .linux => { const outz = spawn.runzCapt(allo, iozz, &.{"xprintidle"}, 64) orelse return null; return std.fmt.parseInt(u64, std.mem.trim(u8, outz, " \r\n"), 10) catch null; }, .macos => { const outz = spawn.runzCapt(allo, iozz, &.{ "ioreg", "-c", "IOHIDSystem", "-d", "4", "-r", "-k", "HIDIdleTime" }, 3000) orelse return null; const keyz = "\"HIDIdleTime\" = "; const atzz = std.mem.indexOf(u8, outz, keyz) orelse return null; var endz = atzz + keyz.len; while (endz < outz.len and std.ascii.isDigit(outz[endz])) endz += 1; const nsec = std.fmt.parseInt(u64, outz[atzz + keyz.len .. endz], 10) catch return null; return nsec / std.time.ns_per_ms; }, else => return null } }
pub fn battOnzz(iozz: std.Io) ?bool { switch (builtin.os.tag) { .windows => return winzBattOnzz(), .linux => { var dirz = std.Io.Dir.cwd().openDir(iozz, "/sys/class/power_supply", .{ .iterate = true }) catch return null; defer dirz.close(iozz); var main_sawz = false; var batt_sawz = false; var iter = dirz.iterate(); while (iter.next(iozz) catch null) |entr| { var tbuf: [256]u8 = undefined; const typz = smalRead(iozz, &tbuf, "/sys/class/power_supply/{s}/type", entr.name) orelse continue; if (std.mem.eql(u8, typz, "Mains")) { main_sawz = true; var obuf: [16]u8 = undefined; const onli = smalRead(iozz, &obuf, "/sys/class/power_supply/{s}/online", entr.name) orelse continue; if (std.mem.eql(u8, onli, "1")) return false; } else if (std.mem.eql(u8, typz, "Battery")) batt_sawz = true; } if (!batt_sawz) return false; return main_sawz; }, .macos => { var bufz: [2048]u8 = undefined; var fbaz = std.heap.FixedBufferAllocator.init(&bufz); const outz = spawn.runzCapt(fbaz.allocator(), iozz, &.{ "pmset", "-g", "batt" }, 1024) orelse return null; if (std.mem.indexOf(u8, outz, "'Battery Power'") != null) return true; if (std.mem.indexOf(u8, outz, "'AC Power'") != null) return false; return null; }, else => return null } }
fn smalRead(iozz: std.Io, outz: []u8, comptime fmtz: []const u8, argz: []const u8) ?[]const u8 { var pbuf: [512]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, fmtz, .{argz}) catch return null; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch return null; defer file.close(iozz); const leng = file.readPositionalAll(iozz, outz, 0) catch return null; return std.mem.trim(u8, outz[0..leng], " \r\n"); }
fn maczProcRunn(iozz: std.Io, name: []const u8) ?bool { var aren = std.heap.ArenaAllocator.init(std.heap.page_allocator); defer aren.deinit(); const outz = spawn.runzCapt(aren.allocator(), iozz, &.{ "ps", "-axco", "command" }, 1024 * 1024) orelse return null; var line = std.mem.splitScalar(u8, outz, '\n'); while (line.next()) |linz| { if (std.mem.eql(u8, std.mem.trim(u8, linz, " \r"), name)) return true; } return false; }
